class Solution:
    def minXor(self, nums: List[int], k: int) -> int:
        n = len(nums)
        pre = [0] * (n + 1)
        for i, x in enumerate(nums):
            pre[i + 1] = pre[i] ^ x
        INF = float('inf')
        dp = [INF] * (n + 1)
        dp[0] = 0
        for j in range(1, k + 1):
            nd = [INF] * (n + 1)
            for i in range(j, n + 1):
                best = INF
                for p in range(j - 1, i):
                    v = max(dp[p], pre[i] ^ pre[p])
                    if v < best:
                        best = v
                nd[i] = best
            dp = nd
        return dp[n]

