class Solution {
public:
    int minXor(vector<int>& nums, int k) {
        int n = nums.size();
        vector<int> pre(n + 1, 0);
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] ^ nums[i];
        const int INF = INT_MAX;
        vector<int> dp(n + 1, INF);
        dp[0] = 0;
        for (int j = 1; j <= k; j++) {
            vector<int> nd(n + 1, INF);
            for (int i = j; i <= n; i++) {
                int best = INF;
                for (int p = j - 1; p < i; p++) {
                    if (dp[p] == INF) continue;
                    best = min(best, max(dp[p], pre[i] ^ pre[p]));
                }
                nd[i] = best;
            }
            dp = nd;
        }
        return dp[n];
    }
};

