class Solution:
    def minXor(self, nums: List[int], k: int) -> int:
        def ok(m):
            parts, cur = 1, 0
            for x in nums:
                if x > m:
                    return False
                if cur ^ x > m:
                    parts += 1
                    cur = x
                else:
                    cur ^= x
            return parts <= k
        lo, hi = 0, (1 << 30) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if ok(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

