class Solution {
public:
    bool ok(vector<int>& nums, int k, long long m) {
        int parts = 1; int cur = 0;
        for (int x : nums) {
            if (x > m) return false;
            if ((cur ^ x) > m) { parts++; cur = x; }
            else cur ^= x;
        }
        return parts <= k;
    }
    int minXor(vector<int>& nums, int k) {
        long long lo = 0, hi = (1LL << 30) - 1;
        while (lo < hi) {
            long long mid = (lo + hi) / 2;
            if (ok(nums, k, mid)) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
};

